{
  "story": "Where do stacking features come from? Follow Fold A, Fold B, and Fold C through Mean and Nearest. Advance with Next to fill the OOF ledger from held-out rows. The meta-model uses that ledger with the original targets. Inputs, folds, and learner rules stay fixed; no tuning or preprocessing occurs.",
  "aha": {
    "stateId": "stacking-ready",
    "observation": "Every OOF feature comes from a base model fitted without that row’s entire fold, not from an all-data fit."
  },
  "layout": {
    "preset": "approved-card: algorithm / collection stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "fold-step-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and instructions. Keep progress on this rail; highlight the active state without implying elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "fold-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical collection composition with fixed, named regions. Keep folds together, followed by learners, ledger, and meta-model. Highlight only bound regions.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor to the active region. Identify its role without repeating numerical readouts. Keep readable label space in every state.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "oof-evidence",
      "kind": "value-readout",
      "presentation": "Place prediction blocks beside the OOF ledger, ordered Mean then Nearest. Show counts as integers without rounding. Render Status as the bound footer.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Previous / Next",
      "presentation": "Detailed parameter-control budget: zero. Navigation uses Previous, Next, and Reset. Default index: zero; bounds: zero through six; increment: one state. Advancing changes training membership, fitted-model counts, or saved prediction evidence. Boundary buttons retain their names when disabled. Buttons support Enter and Space with visible keyboard focus. Every state persists until the learner acts. No timer is used. Reference capture: stacking-ready."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state, unfitted learners, empty OOF ledger, and default navigation index. Support Enter and Space with visible keyboard focus."
    }
